  __ovr_fuel_extrapolated_mass__initial = pop!(__overrides, "fuel_extrapolated_mass__initial", nothing); isnothing(__ovr_fuel_extrapolated_mass__initial) || (__initial_conditions[fuel_extrapolated_mass] = __ovr_fuel_extrapolated_mass__initial)
  __ovr_fuel_extrapolated_mass__guess = pop!(__overrides, "fuel_extrapolated_mass__guess", nothing)

  ### Constants
  __constants = Any[]

  ### Components
  push!(__systems, @named flange = __Dyad__Spline())

  ### Check there are no unmatched overrides
  isempty(__overrides) || throw(ArgumentError("overrides: [$(join(keys(__overrides), ", "))] don't match names found in model. These names may exist in the model but could have been conditionally excluded."))

  ### Guesses
  isnothing(__ovr_rpm__guess) || (__guesses[rpm] = __ovr_rpm__guess)
  isnothing(__ovr_rpm_demand_clamped__guess) || (__guesses[rpm_demand_clamped] = __ovr_rpm_demand_clamped__guess)
  isnothing(__ovr_shaft_w__guess) || (__guesses[shaft_w] = __ovr_shaft_w__guess)
  isnothing(__ovr_err_int__guess) || (__guesses[err_int] = __ovr_err_int__guess)
  isnothing(__ovr_tau_pi__guess) || (__guesses[tau_pi] = __ovr_tau_pi__guess)
  isnothing(__ovr_max_tau__guess) || (__guesses[max_tau] = __ovr_max_tau__guess)
  isnothing(__ovr_tau_cmd__guess) || (__guesses[tau_cmd] = __ovr_tau_cmd__guess)
  isnothing(__ovr_shaft_power__guess) || (__guesses[shaft_power] = __ovr_shaft_power__guess)
  isnothing(__ovr_brake_power__guess) || (__guesses[brake_power] = __ovr_brake_power__guess)
  isnothing(__ovr_brake_power_kW__guess) || (__guesses[brake_power_kW] = __ovr_brake_power_kW__guess)
  isnothing(__ovr_joules__guess) || (__guesses[joules] = __ovr_joules__guess)
  isnothing(__ovr_sfoc__guess) || (__guesses[sfoc] = __ovr_sfoc__guess)
  isnothing(__ovr_load_fuel__guess) || (__guesses[load_fuel] = __ovr_load_fuel__guess)
  isnothing(__ovr_fuel_mass__guess) || (__guesses[fuel_mass] = __ovr_fuel_mass__guess)
  isnothing(__ovr_fuel_extrapolated_mass__guess) || (__guesses[fuel_extrapolated_mass] = __ovr_fuel_extrapolated_mass__guess)

  ### Initialization Equations
  push!(__initialization_eqs, err_int ~ 0)
  push!(__initialization_eqs, joules ~ 0)
  push!(__initialization_eqs, fuel_mass ~ 0)
  push!(__initialization_eqs, fuel_extrapolated_mass ~ 0)
  push!(__initialization_eqs, flange.phi ~ 0)

  ### Assertions
  __assertions = []
  push!(__assertions, (table_knots_valid(SFOC_P) > 0.5 => "SimpleDieselEngine: SFOC_P must be finite, nonnegative and strictly increasing (at SimpleDieselEngine.dyad:213:3)"))
  push!(__assertions, (table_values_valid(SFOC_g) > 0.5 => "SimpleDieselEngine: SFOC_g must be finite and positive (at SimpleDieselEngine.dyad:214:3)"))
  push!(__assertions, (rate_valid(m_dot_idle) > 0.5 => "SimpleDieselEngine: m_dot_idle must be finite and nonnegative (at SimpleDieselEngine.dyad:215:3)"))

  ### Equations
  push!(__eqs, shaft_w ~ ModelingToolkit.D_nounits(flange.phi))
  push!(__eqs, rpm ~ shaft_w * 60 / (2 * π))
  push!(__eqs, rpm_demand_clamped ~ clamp(RPM_demand, RPM_min, RPM_max))
  push!(__eqs, Ti_PI * ModelingToolkit.D_nounits(err_int) ~ rpm_demand_clamped - rpm)
  push!(__eqs, tau_pi ~ clamp(k_PI * ((rpm_demand_clamped - rpm) + err_int), -tau_max_abs, tau_max_abs))
  push!(__eqs, max_tau ~ ifelse(rpm <= 600, 1500, ifelse(rpm <= 800, 1500 + (2000 - 1500) * (rpm - 600) / (800 - 600), ifelse(rpm <= 900, 2000 + (2750 - 2000) * (rpm - 800) / (900 - 800), ifelse(rpm <= 1100, 2750 + (5300 - 2750) * (rpm - 900) / (1100 - 900), ifelse(rpm <= 1200, 5300 + (5500 - 5300) * (rpm - 1100) / (1200 - 1100), ifelse(rpm <= 2100, 5500, ifelse(rpm <= 2300, 5500 + (500 - 5500) * (rpm - 2100) / (2300 - 2100), 500))))))))
  push!(__eqs, tau_cmd ~ clamp(tau_pi, 0, max_tau))
  push!(__eqs, flange.tau ~ -tau_cmd)
  push!(__eqs, shaft_power ~ shaft_w * tau_cmd)
  push!(__eqs, ShaftPower ~ shaft_power)
  push!(__eqs, ModelingToolkit.D_nounits(joules) ~ shaft_power)
  push!(__eqs, KWh ~ joules / 3600000.0)
  push!(__eqs, brake_power ~ positive_part(shaft_power))
  push!(__eqs, brake_power_kW ~ brake_power / 1000)
  push!(__eqs, sfoc ~ table_hold(SFOC_P, SFOC_g, brake_power_kW))
  push!(__eqs, SFOC_valid ~ table_covers(SFOC_P, brake_power_kW))
  push!(__eqs, load_fuel ~ sfoc * brake_power_kW / 3600000.0)
  push!(__eqs, Inst_Fuel ~ load_fuel + m_dot_idle)
  push!(__eqs, ModelingToolkit.D_nounits(fuel_mass) ~ Inst_Fuel)
  push!(__eqs, Fuel ~ fuel_mass)
  push!(__eqs, ModelingToolkit.D_nounits(fuel_extrapolated_mass) ~ (1 - SFOC_valid) * load_fuel)
  push!(__eqs, Fuel_extrapolated ~ fuel_extrapolated_mass)

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export SimpleDieselEngine
